    }
    oss << '"';
    return oss.str();
}

std::string json_stringify(double x) {
    std::ostringstream oss;
    if (std::isnan(x)) {
        oss << "null";
    } else if (std::isinf(x)) {
        oss << (x > 0 ? "null" : "null"); // JSON doesn't have inf; use null per safety
